command:example.dev:code:
using SixLabors.ImageSharp;
using SixLabors.ImageSharp.ColorSpaces;
using var img = Image.Load("in.png");
img.AddText(10, 10, "Sample", Color.Black, 24);
img.Save("out.png");

New-ImageChart -ChartsDefinition {
                New-ImageChartBar -Name 'Q1' -Value 12,18,25 -Color CornflowerBlue
                New-ImageChartBar -Name 'Q2' -Value 14,20,28 -Color Orange
            } -FilePath chart.png -XTitle 'Month' -YTitle 'Revenue'

New-ImageConsoleStory -Title 'pwsh - C:\OpenSource' -WorkingDirectory 'C:\OpenSource' -Theme PowerShell -Content {
              New-ImageConsoleStoryCommand -Text 'Get-Service -Name WinRM'
              New-ImageConsoleStoryOutput -Text 'Status   Name               DisplayName' -Tone Accent
              New-ImageConsoleStoryOutput -Text 'Running  WinRM              Windows Remote Management' -Tone Success
            } -FilePath '.\service-demo.svg'

New-ImageConsoleStory -Dialect CSharp -Title 'dotnet run - ChartForgeX' -Content {
              New-ImageConsoleStoryCommand -Text 'var chart = Chart.Create().WithTitle("Weekly builds");'
              New-ImageConsoleStoryCommand -Text 'chart.SavePng("weekly-builds.png");'
              New-ImageConsoleStoryOutput -Text 'Saved weekly-builds.png' -Tone Success
            } -FilePath '.\chart-demo.gif' -FramesPerSecond 10 -EndHoldSeconds 1.5

New-ImageTopology -TopologyDefinition {
                New-ImageTopologyNode -Id api -Label API -Kind Service -Status Healthy -Symbol API
                New-ImageTopologyNode -Id db -Label Database -Kind Database -Status Warning -Symbol SQL
                New-ImageTopologyEdge -SourceNodeId api -TargetNodeId db -Label '32 ms' -Kind Dependency -Status Warning -Direction Forward
            } -Title 'Service map' -Layout Layered -Direction LeftToRight -FilePath service-map.png

New-ImageVisualStory -StoryScript {
              param($Story)
              [void] $Story.WithTitle('Engineering signal').WithColumns(1)
              $metric = [ChartForgeX.VisualBlocks.MetricCard]::Create().WithMetric('Projects', '126')
              [void] $Story.Add('projects', $metric)
            } -MotionDefinition {
              New-ImageVisualMotionCue -TargetId title -Effect Reveal -DurationSeconds 0.9
              New-ImageVisualMotionCue -TargetId projects -Effect Rise -DelaySeconds 0.3
            } -FilePath profile.svg
